package dev.shadw.asgard.mobs;

import dev.shadw.asgard.Raven;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Raven with its own model and texture. Generated by shadw-mod mob. */
public class RavenRenderer extends MobRenderer<Raven, RavenModel.State, RavenModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("asgard", "textures/entity/raven.png");

	public RavenRenderer(EntityRendererProvider.Context context) {
		super(context, new RavenModel(context.bakeLayer(RavenModel.LAYER)), 0.4F);
	}

	@Override
	public RavenModel.State createRenderState() {
		return new RavenModel.State();
	}

	@Override
	public void extractRenderState(Raven entity, RavenModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(RavenModel.State state) {
		return TEXTURE;
	}
}
